import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken();
        int n = (int) st.nval;
        st.nextToken();
        double D = st.nval;

        double[] P = new double[n];
        double[] C = new double[n];
        for (int i = 0; i < n; i++) {
            st.nextToken();
            P[i] = st.nval;
            st.nextToken();
            C[i] = st.nval;
        }

        double INF = Double.POSITIVE_INFINITY;
        double[] dp = new double[n];
        Arrays.fill(dp, INF);
        dp[0] = 0.0;
        double ans = INF;

        for (int j = 0; j < n; j++) {
            if (dp[j] == INF) continue;
            // opção: ir até o fim com a bateria j
            double seg = D - P[j];
            double t = dp[j] + seg * seg / C[j];
            if (t < ans) ans = t;
            // opção: trocar para bateria k > j
            for (int k = j + 1; k < n; k++) {
                double L = P[k] - P[j];
                double t2 = dp[j] + L * L / C[j];
                if (t2 < dp[k]) dp[k] = t2;
            }
        }

        System.out.printf(Locale.US, "%.3f%n", ans);
    }
}
